import pytest


def age_at(born: int, now: int) -> int:
    """Whole years between the birth year `born` and the current year `now`.

    The current year is supplied by the caller; the clock is never read.
    Only years are known, so the result is `now - born`.

    Raises ValueError if `now` is earlier than `born`.
    """
    if now < born:
        raise ValueError("now is earlier than born")
    return now - born


def test_age_typical() -> None:
    assert age_at(1990, 2024) == 34


def test_age_same_year_is_zero() -> None:
    assert age_at(2000, 2000) == 0


def test_age_one_year() -> None:
    assert age_at(1999, 2000) == 1


def test_age_century_span() -> None:
    assert age_at(1900, 2000) == 100


def test_age_small_years() -> None:
    assert age_at(1, 2) == 1
    assert age_at(0, 0) == 0


def test_age_now_before_born_raises() -> None:
    with pytest.raises(ValueError):
        age_at(2001, 2000)


def test_age_returns_int() -> None:
    assert isinstance(age_at(1980, 2020), int)
